import { test } from 'node:test';
import assert from 'node:assert/strict';
import {
  decodeCursor,
  encodeCursor,
  InvalidCursorError,
  paginate,
} from './pagination.js';

const functions = [encodeCursor, decodeCursor, paginate];
const skip = functions.some((fn) => fn.toString().includes('TODO'))
  ? 'exercise not started — remove all TODO markers to activate checks'
  : false;

const rows = [
  { id: 4, createdAt: '2026-03-03T10:00:00.000Z', title: 'newest' },
  { id: 3, createdAt: '2026-03-02T10:00:00.000Z', title: 'tie-high-id' },
  { id: 2, createdAt: '2026-03-02T10:00:00.000Z', title: 'tie-low-id' },
  { id: 1, createdAt: '2026-03-01T10:00:00.000Z', title: 'oldest' },
];

test('cursor round-trips only the stable ordering fields', { skip }, () => {
  const encoded = encodeCursor(rows[1]);
  assert.equal(typeof encoded, 'string');
  assert.ok(encoded.length > 0);
  assert.deepEqual(decodeCursor(encoded), {
    createdAt: '2026-03-02T10:00:00.000Z',
    id: 3,
  });
  assert.equal(encoded.includes('tie-high-id'), false);
});

test('first page sorts descending and reports more data', { skip }, () => {
  const shuffled = [rows[2], rows[0], rows[3], rows[1]];
  const page = paginate(shuffled, { limit: 2 });

  assert.deepEqual(page.items.map((row) => row.id), [4, 3]);
  assert.equal(page.pageInfo.hasNextPage, true);
  assert.deepEqual(decodeCursor(page.pageInfo.nextCursor), {
    createdAt: rows[1].createdAt,
    id: 3,
  });
});

test('the next page begins strictly after the cursor', { skip }, () => {
  const first = paginate(rows, { limit: 2 });
  const second = paginate(rows, { limit: 2, cursor: first.pageInfo.nextCursor });

  assert.deepEqual(second.items.map((row) => row.id), [2, 1]);
  assert.deepEqual(second.pageInfo, { hasNextPage: false, nextCursor: null });
});

test('a newer insert between requests causes no duplicate or skipped old row', { skip }, () => {
  const first = paginate(rows, { limit: 2 });
  const changed = [
    { id: 5, createdAt: '2026-03-04T10:00:00.000Z', title: 'inserted later' },
    ...rows,
  ];
  const second = paginate(changed, { limit: 2, cursor: first.pageInfo.nextCursor });

  assert.deepEqual(first.items.map((row) => row.id), [4, 3]);
  assert.deepEqual(second.items.map((row) => row.id), [2, 1]);
});

test('input order and objects are not mutated', { skip }, () => {
  const input = [rows[3], rows[0], rows[1]];
  const snapshot = structuredClone(input);
  paginate(input, { limit: 2 });
  assert.deepEqual(input, snapshot);
});

test('invalid limits fail at the boundary', { skip }, () => {
  for (const limit of [0, -1, 1.5, 101, NaN, '10']) {
    assert.throws(() => paginate(rows, { limit }), /limit/i);
  }
});

test('malformed and incomplete cursors have one typed failure', { skip }, () => {
  for (const cursor of ['garbage', '', Buffer.from('{}').toString('base64url')]) {
    assert.throws(() => decodeCursor(cursor), InvalidCursorError);
    assert.throws(() => paginate(rows, { cursor }), InvalidCursorError);
  }
});

test('empty input is a complete empty page', { skip }, () => {
  assert.deepEqual(paginate([], { limit: 10 }), {
    items: [],
    pageInfo: { hasNextPage: false, nextCursor: null },
  });
});

export class InvalidCursorError extends Error {
  constructor(message = 'invalid pagination cursor') {
    super(message);
    this.name = 'InvalidCursorError';
  }
}

